    public init(
        data: LocalDataService,
        betaPolicyOverride: ApplicationsBetaPolicy? = nil,
        catalogDataLoader: (() throws -> Data)? = nil,
        catalogRefreshDataLoader: (() async throws -> Data)? = nil,
        catalogPageDataLoader:
            ((String, String?, String?, Int) async throws -> Data)? = nil,
        catalogDetailDataLoader: ((String) async throws -> Data)? = nil
    ) {
        self.data = data
        self.betaPolicyOverride = betaPolicyOverride
        let resolvedCatalogDataLoader = catalogDataLoader ?? Self.loadBundledMarketplaceCatalogData
        self.catalogDataLoader = resolvedCatalogDataLoader
        self.catalogRefreshDataLoader = catalogRefreshDataLoader ?? { try resolvedCatalogDataLoader() }
        self.catalogPageDataLoader = catalogPageDataLoader
        self.catalogDetailDataLoader = catalogDetailDataLoader
    }

    static func loadBundledMarketplaceCatalogData() throws -> Data {
        guard let url = Bundle.module.url(
            forResource: "marketplace-provider-catalog",
            withExtension: "json"
        ) else {
            throw RelayError(.internalError, "The generated Marketplace catalog is missing.")
        }
        return try Data(contentsOf: url)
    }

    static func loadRailwayMarketplaceCatalogData(origin: String) async throws -> Data {
        try await loadRailwayMarketplaceCatalogPageData(
            origin: origin,
            query: "",
            category: nil,
            cursor: nil,
            limit: 50
        )
    }

    static func loadRailwayMarketplaceCatalogPageData(
        origin: String,
        query: String,
        category: String?,
        cursor: String?,
        limit: Int
    ) async throws -> Data {
        let normalizedOrigin = origin.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        guard var components = URLComponents(
            string: "\(normalizedOrigin)/api/v1/marketplace/catalog"
        ) else {
            throw RelayError(.invalidInput, "The Railway Marketplace origin is invalid.")
        }
        components.queryItems = [
            URLQueryItem(name: "limit", value: String(min(max(limit, 1), 100))),
            URLQueryItem(
                name: "query",
                value: nonEmpty(query)
            ),
            URLQueryItem(name: "category", value: category.flatMap(nonEmpty)),
            URLQueryItem(name: "cursor", value: cursor.flatMap(nonEmpty)),
        ].filter { $0.value != nil }
        guard let url = components.url else {
            throw RelayError(.invalidInput, "The Railway Marketplace request is invalid.")
        }
        var request = URLRequest(url: url, timeoutInterval: 8)
        request.setValue("application/json", forHTTPHeaderField: "Accept")
        let (responseData, response) = try await URLSession.shared.data(for: request)
        guard let response = response as? HTTPURLResponse,
              (200..<300).contains(response.statusCode),
              !responseData.isEmpty
        else {
            throw RelayError(.dispatchFailed, "Railway did not return the Marketplace catalog.")
        }
        return responseData
    }

    private static func nonEmpty(_ value: String) -> String? {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    static func loadRailwayMarketplaceAppData(
        origin: String,
        slug: String
    ) async throws -> Data {
        let normalizedOrigin = origin.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        guard let encodedSlug = slug.addingPercentEncoding(
            withAllowedCharacters: .urlPathAllowed
        ), let url = URL(
            string: "\(normalizedOrigin)/api/v1/marketplace/public-catalog/\(encodedSlug)"
        ) else {
            throw RelayError(.invalidInput, "The Railway Marketplace app is invalid.")
        }
        var request = URLRequest(url: url, timeoutInterval: 8)
        request.setValue("application/json", forHTTPHeaderField: "Accept")
        let (responseData, response) = try await URLSession.shared.data(for: request)
        guard let response = response as? HTTPURLResponse,
              (200..<300).contains(response.statusCode),
              !responseData.isEmpty
        else {
            throw RelayError(.dispatchFailed, "Railway did not return the Marketplace app.")
        }
        return responseData
    }

    @discardableResult
    public func saveCatalogApps(context: ServiceRequestContext, apps: [MarketplaceCatalogApp]) throws -> [MarketplaceCatalogApp] {
        if let denied = ServiceGuard.requireAnyRole([.owner, .admin], context: context) {
            throw denied
        }
        for app in apps where app.workspaceId != context.workspaceId {
            throw ServiceGuard.invalidInput(context: context, message: "Marketplace app workspace does not match the request context.")
        }
        return try data.saveMarketplaceCatalogApps(apps)
    }

    public func catalogSnapshot(
        context: ServiceRequestContext,
        filter: ApplicationsCatalogFilter = ApplicationsCatalogFilter(view: .all, searchQuery: "", category: nil, riskLevel: nil),
        selectedAppId: RelayId? = nil,
        now: Date = Date()
    ) throws -> ApplicationsCatalogSnapshot {
        try makeCatalogSnapshot(
            context: context,
            filter: filter,
            selectedAppId: selectedAppId,
            now: now,
            catalogData: catalogDataLoader()
        )
    }

    public func refreshCatalogSnapshot(
        context: ServiceRequestContext,
        filter: ApplicationsCatalogFilter = ApplicationsCatalogFilter(view: .all, searchQuery: "", category: nil, riskLevel: nil),
        selectedAppId: RelayId? = nil,
        cursor: String? = nil,
        accumulatingApps: [MarketplaceCatalogApp] = [],
        now: Date = Date()
    ) async throws -> ApplicationsCatalogSnapshot {
        let catalogData: Data
        if let catalogPageDataLoader {
            catalogData = try await catalogPageDataLoader(
                filter.searchQuery,
                filter.category,
                cursor,
                50
            )
        } else {
            catalogData = try await catalogRefreshDataLoader()
        }
        var selectedDetailRecord: [String: Any]?
        if let selectedAppId,
           let catalogDetailDataLoader {
            let selectedSummary = try Self.catalogRecords(from: catalogData).first(where: {
                let slug = $0["slug"] as? String
                return slug == selectedAppId || "mapp-\(slug ?? "")" == selectedAppId
            })
            let selectedSlug =
                (selectedSummary?["slug"] as? String)
                ?? Self.marketplaceSlug(fromSelectedAppId: selectedAppId)
            if let slug = selectedSlug,
               let detailData = try? await catalogDetailDataLoader(slug) {
                selectedDetailRecord =
                    (try? Self.catalogRecords(from: detailData).first)
                    ?? Self.catalogRecord(fromSingleAppData: detailData)
            }
        }
        return try makeCatalogSnapshot(
            context: context,
            filter: filter,
            selectedAppId: selectedAppId,
            now: now,
            catalogData: catalogData,
            accumulatingApps: accumulatingApps,
            selectedDetailRecord: selectedDetailRecord
        )
    }

    private static func marketplaceSlug(fromSelectedAppId selectedAppId: RelayId) -> String? {
        let candidate =
            selectedAppId.hasPrefix("mapp-")
            ? String(selectedAppId.dropFirst("mapp-".count))
            : selectedAppId
        guard candidate.range(
            of: #"^[a-z0-9]+(?:-[a-z0-9]+)*$"#,
            options: .regularExpression
        ) != nil else {
            return nil
        }
        return candidate
    }

    private func makeCatalogSnapshot(
        context: ServiceRequestContext,
        filter: ApplicationsCatalogFilter,
        selectedAppId: RelayId?,
        now: Date,
        catalogData: Data,
        accumulatingApps: [MarketplaceCatalogApp] = [],
        selectedDetailRecord: [String: Any]? = nil
    ) throws -> ApplicationsCatalogSnapshot {
        if let denied = ServiceGuard.requireAnyRole([.owner, .admin, .member], context: context) {
            throw denied
        }

        let timestamp = ISO8601DateFormatter.relayConsole.string(from: now)
        let betaPolicy = try betaPolicyOverride ?? ApplicationsBetaPolicy.loadCurrent()
        var catalogRecords = try Self.catalogRecords(from: catalogData).filter { record in
            guard let slug = record["slug"] as? String else { return false }
            return betaPolicy.approvedSlugs.contains(slug)
        }
        if let selectedDetailRecord,
           let detailSlug = selectedDetailRecord["slug"] as? String,
           betaPolicy.approvedSlugs.contains(detailSlug) {
            if let detailIndex = catalogRecords.firstIndex(where: {
                ($0["slug"] as? String) == detailSlug
            }) {
                catalogRecords[detailIndex] = selectedDetailRecord
            } else {
                catalogRecords.append(selectedDetailRecord)
            }
        }
        let pagination = Self.catalogPagination(from: catalogData)
        let knownProviderSlugs = catalogRecords.compactMap { $0["slug"] as? String }
        let missingProviderSlugs = Set(betaPolicy.approvedSlugs).subtracting(knownProviderSlugs).sorted()
        guard pagination != nil || missingProviderSlugs.isEmpty else {
            throw RelayError(
                .internalError,
                "The public-beta Applications policy contains unknown provider slugs: \(missingProviderSlugs.joined(separator: ", "))."
            )
        }
        let persistedApps = try data.listMarketplaceCatalogApps(workspaceId: context.workspaceId)
        let pageApps = try Self.canonicalCatalogApps(
            workspaceId: context.workspaceId,
            catalogRecords: catalogRecords,
            persistedApps: persistedApps,
            timestamp: timestamp,
            data: data,
            betaPolicy: betaPolicy
        )
        let allApps = Self.mergeCatalogApps(accumulatingApps, pageApps)
        let readOnly = !context.hasAnyRole([.owner, .admin])
        let tabs = Self.tabs(for: allApps, context: context)
        let effectiveFilter = ApplicationsCatalogFilter(
            view: .all,
            searchQuery: filter.searchQuery,
            category: filter.category,
            riskLevel: nil
        )
        let filtered = Self.filteredApps(Self.apps(in: .all, from: allApps), filter: effectiveFilter)
        let selectedApp = selectedAppId.flatMap { id in
            filtered.first { $0.id == id || $0.slug == id } ?? allApps.first { $0.id == id || $0.slug == id }
        } ?? filtered.first
        let state: ApplicationsCatalogState
        if allApps.isEmpty {
            state = .empty
        } else if filtered.isEmpty {
            state = .noMatch
        } else {
            state = .ready
        }
        let categories =
            Self.catalogCategories(from: catalogData)
            ?? Array(Set(allApps.map(\.category))).sorted()
        let diagnostics = ApplicationsCatalogDiagnostics(
            endpointLabel: "Railway canonical Marketplace catalog",
            responseCount: pagination?.totalCount ?? allApps.count,
            selectedCategory: effectiveFilter.category ?? "All categories",
            riskFilter: "Not shown",
            searchQuery: effectiveFilter.searchQuery.isEmpty ? "None" : effectiveFilter.searchQuery,
            demoFallbackUsed: false,
            message: diagnosticsMessage(state: state)
        )
        let snapshot = ApplicationsCatalogSnapshot(
            workspaceId: context.workspaceId,
            state: state,
            refreshedAt: timestamp,
            filter: effectiveFilter,
            tabs: tabs,
            categories: categories,
            riskLevels: [],
            apps: filtered,
            selectedApp: selectedApp,
            diagnostics: diagnostics,
            betaNotice: "\(betaPolicy.approvedSlugs.count) bounded launch providers are available. Connection status is tracked separately for this workspace.",
            readOnly: readOnly,
            redactionStatus: "private-state-excluded",
            nextCursor: pagination?.nextCursor,
            totalCount: pagination?.totalCount
        )
        try data.saveApplicationsNavigationRecord(
            workspaceId: context.workspaceId,
            sectionKey: ShellSectionKey.applications.rawValue,
            label: "Applications",
            policy: .active,
            stateKind: nil,
            reasonCode: nil,
            visibleToRoles: [.owner, .admin, .member],
            message: "Applications Marketplace is backed by Railway's canonical provider-manifest catalog.",
            navigation: [
                "marketplace": .string("active"),
                "localApps": .string("excluded"),
                "reviewUpdates": .string("excluded"),
                "paperclip": .string("excluded")
            ]
        )
        return try data.saveApplicationsCatalogSnapshot(snapshot)
    }

    public func latestSnapshot(context: ServiceRequestContext) throws -> ApplicationsCatalogSnapshot? {
        if let denied = ServiceGuard.requireAnyRole([.owner, .admin, .member], context: context) {
            throw denied
        }
        return try data.latestApplicationsCatalogSnapshot(workspaceId: context.workspaceId)
    }

    public static func iconFallback(slug: String, name: String) -> MarketplaceIconFallback {
        let words = name
            .split(separator: " ")
            .prefix(2)
            .map { String($0.prefix(1)).uppercased() }
        let initials = words.isEmpty ? String(slug.prefix(2)).uppercased() : words.joined()
        let palette = ["blue", "green", "amber", "purple", "teal", "red"]
        let total = slug.unicodeScalars.reduce(0) { $0 + Int($1.value) }
        return MarketplaceIconFallback(
            initials: String(initials.prefix(3)),
            colorName: palette[abs(total) % palette.count],
            source: "deterministic-slug-fallback"
        )
    }

    public static func rowActionTitle(for app: MarketplaceCatalogApp) -> String {
        switch app.availability {
        case .betaUnavailable, .unavailable:
            return "Unavailable"
        case .comingSoon:
            return "View"
        case .available:
            if app.installState == .installed {
                return "View"
            }
            return app.connectionState == .connected ? "Install" : "Connect"
        }
    }

    public static func rowStatusTitle(for app: MarketplaceCatalogApp) -> String {
        switch app.availability {
        case .betaUnavailable:
            return app.betaNotice ?? "Not in current beta"
        case .comingSoon:
            return app.betaNotice ?? "Coming later"
        case .unavailable:
            return app.betaNotice ?? app.availabilityReason ?? "Unavailable"
        case .available:
            if app.installState == .installed {
                return "Installed to \(app.installedAgentCount) agent\(app.installedAgentCount == 1 ? "" : "s")"
            }
            if app.connectionState == .connected {
                return "Connected, not installed"
            }
        return "No connection yet"
        }
    }

    private static func tabs(for apps: [MarketplaceCatalogApp], context: ServiceRequestContext) -> [ApplicationsCatalogTab] {
        [
            ApplicationsCatalogTab(
                view: .all,
                label: "Apps",
                count: apps.count,
                enabled: true,
                stateKind: nil,
                reasonCode: nil,
                message: nil,
                visibleToRoles: [.owner, .admin, .member]
            )
        ]
    }

    private static func apps(in view: ApplicationsCatalogView, from apps: [MarketplaceCatalogApp]) -> [MarketplaceCatalogApp] {
        switch view {
        case .all, .external:
            return apps
        case .connections, .installed, .local, .review:
            return []
        }
    }

    private static func filteredApps(_ apps: [MarketplaceCatalogApp], filter: ApplicationsCatalogFilter) -> [MarketplaceCatalogApp] {
        let query = filter.searchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return apps.filter { app in
            let matchesQuery = query.isEmpty || [
                app.name,
                app.slug,
                app.summary,
                app.description,
                app.category,
                app.capabilities.joined(separator: " ")
            ].joined(separator: " ").lowercased().contains(query)
            let matchesCategory = filter.category.map { app.category == $0 } ?? true
            let matchesRisk = true
            return matchesQuery && matchesCategory && matchesRisk
        }
    }

    private static func canonicalCatalogApps(
        workspaceId: RelayId,
        catalogRecords: [[String: Any]],
        persistedApps: [MarketplaceCatalogApp],
        timestamp: IsoTimestamp,
        data: LocalDataService,
        betaPolicy: ApplicationsBetaPolicy
    ) throws -> [MarketplaceCatalogApp] {
        var visibleBySlug: [String: MarketplaceCatalogApp] = [:]
        let catalogSlugs = Set(catalogRecords.compactMap { $0["slug"] as? String })
        for app in persistedApps where catalogSlugs.contains(app.slug)
            && app.sourceType == .externalProvider
            && !app.localAppExcluded
            && !app.reviewExcluded
            && !app.slug.localizedCaseInsensitiveContains("paperclip") {
            visibleBySlug[app.slug] = visibleBySlug[app.slug] ?? app
        }
        var gatedApps: [MarketplaceCatalogApp] = []
        var recordsToSave: [String: MarketplaceCatalogApp] = [:]
        for record in catalogRecords {
            guard let slug = record["slug"] as? String else { continue }
            var canonical = app(
                fromCatalogRecord: record,
                workspaceId: workspaceId,
                timestamp: timestamp
            )
            let persisted = visibleBySlug[slug]
            if let persisted {
                canonical.connectionState = persisted.connectionState
                canonical.installState = persisted.installState
                canonical.installedAgentCount = persisted.installedAgentCount
                canonical.installedAgentIds = persisted.installedAgentIds
                canonical.createdAt = persisted.createdAt
                canonical.updatedAt = persisted.updatedAt
            }

            var gated = betaPolicy.apply(to: canonical)
            gated.name = redactString(gated.name)
            gated.summary = redactString(gated.summary)
            gated.description = redactString(gated.description)
            gated.availabilityReason = gated.availabilityReason.map(redactString)
            gated.betaNotice = gated.betaNotice.map(redactString)
            gated.redactionStatus = "private-state-excluded"
            if persisted != gated {
                gated.updatedAt = timestamp
                recordsToSave[slug] = gated
            }
            gatedApps.append(gated)
        }
        if !recordsToSave.isEmpty {
            _ = try data.saveMarketplaceCatalogApps(Array(recordsToSave.values))
        }
        return gatedApps
    }

    private static func catalogRecords(from data: Data) throws -> [[String: Any]] {
        guard let root = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            throw RelayError(.internalError, "The Marketplace catalog response is invalid.")
        }
        let payload = (root["data"] as? [String: Any]) ?? root
        if let apps = payload["apps"] as? [[String: Any]] { return apps }
        if let manifests = payload["manifests"] as? [[String: Any]] { return manifests }
        if payload["slug"] is String { return [payload] }
        throw RelayError(.internalError, "The Marketplace catalog contains no provider records.")
    }

    private struct CatalogPagination {
        var nextCursor: String?
        var totalCount: Int
    }

    private static func catalogPagination(from data: Data) -> CatalogPagination? {
        guard let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return nil
        }
        let payload = (root["data"] as? [String: Any]) ?? root
        guard let pageInfo = payload["pageInfo"] as? [String: Any],
              let totalCount = pageInfo["totalCount"] as? Int else {
            return nil
        }
        return CatalogPagination(
            nextCursor: pageInfo["nextCursor"] as? String,
            totalCount: totalCount
        )
    }

    private static func catalogCategories(from data: Data) -> [String]? {
        guard let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return nil
        }
        let payload = (root["data"] as? [String: Any]) ?? root
        guard let categories = payload["categories"] as? [[String: Any]] else {
            return nil
        }
        return categories.compactMap { category in
            let label = category["label"] as? String
            return label.flatMap(nonEmpty)
        }
    }

    private static func catalogRecord(fromSingleAppData data: Data) -> [String: Any]? {
        guard let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return nil
        }
        return (root["data"] as? [String: Any]) ?? root
    }

    private static func mergeCatalogApps(
        _ existing: [MarketplaceCatalogApp],
        _ page: [MarketplaceCatalogApp]
    ) -> [MarketplaceCatalogApp] {
        var bySlug: [String: MarketplaceCatalogApp] = [:]
        for app in existing { bySlug[app.slug] = app }
        for app in page { bySlug[app.slug] = app }
        return bySlug.values.sorted {
            $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending
        }
    }

