    static func marketplaceGenericRailwayApp(
        workspaceId: RelayId,
        slug: String,
        timestamp: IsoTimestamp
    ) -> MarketplaceCatalogApp {
        let metadata = genericRailwayCatalogMetadata(slug: slug)
        let isPreview = metadata.availability != .available
        let blocked = ["raw_provider_api", "credential_export", "local_file_write", "host_control", "paperclip"]
        return MarketplaceCatalogApp(
            id: "mapp-\(slug)", workspaceId: workspaceId, slug: slug, name: metadata.name,
            summary: isPreview
                ? "Preview \(metadata.name) while provider approval or a supported authentication contract is pending."
                : "Connect \(metadata.name) through Railway and use its bounded Marketplace actions under agent policy.",
            description: catalogProductDescriptions[slug]
                ?? "\(metadata.name) is exposed through ClawChat's Railway-backed Marketplace catalog.",
            category: metadata.category, sourceType: .externalProvider, riskLevel: .high,
            authType: metadata.authType, connectionType: metadata.connectionType,
            capabilities: isPreview
                ? ["Review product capabilities and provider requirements", "Keep connection and actions disabled until the provider contract is approved"]
                : ["Use the bounded provider operations published by Railway", "Apply provider authority and ClawChat approval policy", "Keep credentials encrypted and execute through the Railway connector"],
            runtimeSupport: [.hermes, .openclaw],
            roleManifest: MarketplaceRoleManifest(
                primaryRole: "operator", supportedRoles: ["operator"],
                compatibleRuntimeTypes: [.hermes, .openclaw], approvalRequired: true,
                roleDefinitions: [MarketplaceInstallRoleDefinition(
                    roleId: "operator", label: "Operator",
                    purpose: isPreview
                        ? "Preview \(metadata.name) while connection and provider actions remain disabled."
                        : "Use Railway-published \(metadata.name) actions under the selected connection and approval policy.",
                    canWrite: !isPreview, readOnly: isPreview, approvalRequiredActions: [],
                    blockedActions: blocked, required: true, installAfterSetup: !isPreview,
                    installable: !isPreview,
                    notInstallableReason: isPreview ? metadata.availabilityReason : nil,
                    recommendedAgentRole: "operator", source: "railway-generic-marketplace",
                    redactionStatus: "private-state-excluded")],
                redactionStatus: "private-state-excluded"),
            availability: metadata.availability, availabilityReason: metadata.availabilityReason,
            connectionState: .none, installState: .notInstalled, installedAgentCount: 0,
            installedAgentIds: [], docsURL: metadata.docsURL, websiteURL: metadata.websiteURL,
            betaNotice: isPreview ? metadata.availabilityReason : "Provider setup and live acceptance are completed on Railway.",
            iconFallback: iconFallback(slug: slug, name: metadata.name), readOnly: isPreview,
            localAppExcluded: false, reviewExcluded: false, createdAt: timestamp, updatedAt: timestamp,
            redactionStatus: "private-state-excluded")
    }

    private static func genericRailwayCatalogMetadata(slug: String) -> (
        name: String, category: String, authType: String, connectionType: String,
        availability: MarketplaceAppAvailabilityState, availabilityReason: String?,
        docsURL: String, websiteURL: String
    ) {
        let rows: [String: (String, String, String, String, MarketplaceAppAvailabilityState, String?, String, String)] = [
            "when-i-work": (
                "When I Work", "Work Management", "Provider-approved authentication pending", "Provider partnership required", .comingSoon, "Connect remains disabled until When I Work approves Relay's technology partnership and authentication contract.",
                "https://apidocs.wheniwork.com/external/index.html", "https://wheniwork.com/"
            ),
            "deputy": ("Deputy", "Work Management", "OAuth 2.0", "Relay-owned OAuth via Railway", .available, nil, "https://developer.deputy.com/", "https://www.deputy.com/"),
            "homebase": ("Homebase", "Work Management", "API key", "Railway encrypted API-key connection", .available, nil, "https://app.joinhomebase.com/api-docs", "https://www.joinhomebase.com/"),
            "7shifts": ("7shifts", "Work Management", "OAuth 2.0", "Relay-owned OAuth via Railway", .available, nil, "https://developers.7shifts.com/reference", "https://www.7shifts.com/"),
            "sling": ("Sling", "Work Management", "Supported third-party authentication pending", "Provider review required", .comingSoon, "Connect remains disabled until Sling approves a supported third-party authentication contract.", "https://api.getsling.com/", "https://getsling.com/"),
            "float": (
                "Float", "Work Management", "OAuth 2.0 provider review pending", "Provider-reviewed Railway connection", .comingSoon, "Connect remains disabled while Float MCP beta eligibility and third-party OAuth acceptance are pending.",
                "https://support.float.com/en/articles/12688168-float-mcp-beta", "https://www.float.com/"
            ),
            "resource-guru": ("Resource Guru", "Work Management", "OAuth 2.0", "Relay-owned OAuth via Railway", .available, nil, "https://resourceguruapp.com/docs/api", "https://resourceguruapp.com/"),
            "runn": ("Runn", "Work Management", "API token", "Railway encrypted regional token connection", .available, nil, "https://developer.runn.io/docs/getting-started", "https://www.runn.io/"),
            "everhour": ("Everhour", "Work Management", "API key", "Railway encrypted API-key connection", .available, nil, "https://everhour.docs.apiary.io/", "https://everhour.com/"),
            "timely-time-tracking": ("Timely Time Tracking", "Work Management", "OAuth 2.0", "Relay-owned OAuth via Railway", .available, nil, "https://developer.timely.com/", "https://www.timely.com/"),
            "rescuetime": ("RescueTime", "Work Management", "OAuth 2.0", "Relay-owned OAuth via Railway", .available, nil, "https://www.rescuetime.com/api-docs", "https://www.rescuetime.com/"),
            "time-doctor": ("Time Doctor", "Work Management", "JWT access token", "Railway encrypted token connection", .available, nil, "https://timedoctor.redoc.ly/", "https://www.timedoctor.com/"),
            "hubstaff": ("Hubstaff", "Work Management", "OIDC OAuth 2.0 with PKCE", "Relay-owned OAuth via Railway", .available, nil, "https://developer.hubstaff.com/", "https://hubstaff.com/"),
            "quickbooks-time": ("QuickBooks Time", "Work Management", "Access token", "Railway encrypted token connection", .available, nil, "https://tsheetsteam.github.io/api_docs/", "https://quickbooks.intuit.com/time-tracking/"),
            "replicon": ("Replicon", "Work Management", "Company key and access token", "Railway encrypted tenant token connection", .available, nil, "https://sb1.replicon.com/services/docs/projects.html", "https://www.replicon.com/"),
            "actitime": ("actiTIME", "Work Management", "Installation credentials", "Railway encrypted Basic-auth connection", .available, nil, "https://www.actitime.com/api-documentation", "https://www.actitime.com/"),
            "trackingtime": ("TrackingTime", "Work Management", "App password", "Railway encrypted hosted-MCP connection", .available, nil, "https://support.trackingtime.co/en/articles/13738626-trackingtime-mcp-server-for-ai-assistants", "https://trackingtime.co/"),
            "my-hours": ("My Hours", "Work Management", "API key", "Railway encrypted API-key connection", .available, nil, "https://documenter.getpostman.com/view/8879268/TVmV4YYU", "https://myhours.com/"),
            "paperform": ("Paperform", "Forms & Surveys", "API key", "Railway encrypted regional API-key connection", .available, nil, "https://paperform.readme.io/reference/getting-started-1", "https://paperform.co/"),
            "cognito-forms": ("Cognito Forms", "Forms & Surveys", "OAuth 2.0 with PKCE", "Relay-owned OAuth via Railway", .available, nil, "https://www.cognitoforms.com/support/1038/data-integration/mcp-connector", "https://www.cognitoforms.com/"),
            "wufoo": ("Wufoo", "Forms & Surveys", "API key", "Railway encrypted account-bound API-key connection", .available, nil, "https://wufoo.github.io/docs/", "https://www.wufoo.com/"),
            "coda": ("Coda", "Workspace", "API token", "Railway encrypted token connection", .available, nil, "https://coda.io/developers/apis/v1", "https://coda.io/"),
            "ghost": ("Ghost", "Publishing", "Custom integration Admin API key", "Railway encrypted site-bound key connection", .available, nil, "https://ghost.org/docs/admin-api/", "https://ghost.org/"),
            "zoho": ("Zoho CRM", "CRM", "OAuth 2.0", "Relay-owned multi-region OAuth via Railway", .available, nil, "https://www.zoho.com/crm/developer/docs/api/v8/", "https://www.zoho.com/crm/")
        ]
        guard let row = rows[slug] else {
            let name = slug.split(separator: "-").map { $0.capitalized }.joined(separator: " ")
            return (name, "Marketplace", "Railway-managed provider authentication", "Railway provider connection", .comingSoon, "The canonical provider catalog entry is not available in this client build.", "https://clawchat-staging.up.railway.app", "https://clawchat-staging.up.railway.app")
        }
        return (row.0, row.1, row.2, row.3, row.4, row.5, row.6, row.7)
    }

