    private func diagnosticsMessage(state: ApplicationsCatalogState) -> String {
        switch state {
        case .loading:
            return "Loading marketplace apps"
        case .ready:
            return "Applications Marketplace"
        case .empty:
            return "No apps available"
        case .noMatch:
            return "No apps match your search"
        case .unavailable:
            return "Applications Marketplace is unavailable."
        case .error:
            return "Could not load marketplace apps"
        }
    }
